{"query": "WITH nk AS (
  SELECT Ensembl AS ens, Gene AS sym
  FROM proteinatlas
  WHERE "RNA blood lineage specificity"='Lineage enriched' AND split_part("RNA blood lineage specific nTPM",':',1)='NK-cells'
)
SELECT sym FROM nk WHERE sym LIKE 'CD%' ORDER BY sym"}

{"query": "WITH b AS (
  SELECT Ensembl AS ens, Gene AS sym
  FROM proteinatlas
  WHERE "RNA blood lineage specificity"='Lineage enriched' AND split_part("RNA blood lineage specific nTPM",':',1)='B-cells'
)
SELECT sym FROM b WHERE sym LIKE 'CD%' ORDER BY sym"}
